import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const k=JSON.parse('{"title":"Networking","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/networking.md","filePath":"concepts/networking.md"}'),n={name:"concepts/networking.md"};function r(l,s,p,o,d,h){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="networking" tabindex="-1">Networking <a class="header-anchor" href="#networking" aria-label="Permalink to &quot;Networking&quot;">​</a></h1><p>Service networking in CCattler is built on derived facts — endpoints are computed from running instances, not manually managed. When instances move, endpoints update automatically.</p><h2 id="endpoints-as-derived-facts" tabindex="-1">Endpoints as derived facts <a class="header-anchor" href="#endpoints-as-derived-facts" aria-label="Permalink to &quot;Endpoints as derived facts&quot;">​</a></h2><p>The endpoint controller watches for running, healthy instances and creates endpoint facts:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>service web, instances 3, expose 8080</span></span>
<span class="line"><span>  →</span></span>
<span class="line"><span>endpoint(web) = {10.0.1.4:8080, 10.0.2.8:8080, 10.0.3.2:8080}</span></span></code></pre></div><p>Instance disappears → endpoint set updates automatically. No manual service registration.</p><h2 id="service-vips" tabindex="-1">Service VIPs <a class="header-anchor" href="#service-vips" aria-label="Permalink to &quot;Service VIPs&quot;">​</a></h2><p>Each service gets a virtual IP from the <code>10.200.0.0/24</code> pool. VIPs are stable across instance changes — clients connect to the VIP and traffic is distributed to healthy backends.</p><h2 id="dns-resolution" tabindex="-1">DNS resolution <a class="header-anchor" href="#dns-resolution" aria-label="Permalink to &quot;DNS resolution&quot;">​</a></h2><p>CCattler runs a DNS server (enabled with <code>cca server --dns</code>) that resolves service names:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web.ccattler.local</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @localhost</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 15353</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Returns: 10.200.0.1 (the service VIP)</span></span></code></pre></div><p>Any service name resolves to its VIP. No service mesh sidecar needed.</p><h2 id="http-reverse-proxy" tabindex="-1">HTTP reverse proxy <a class="header-anchor" href="#http-reverse-proxy" aria-label="Permalink to &quot;HTTP reverse proxy&quot;">​</a></h2><p>Each agent runs an HTTP reverse proxy (enabled with <code>cca agent --proxy</code>) that routes by Host header:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Host: web&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://node-address:80</span></span></code></pre></div><p>The proxy performs round-robin load balancing across healthy backends. When instances are added or removed, the backend pool updates automatically.</p><h2 id="cross-host-networking" tabindex="-1">Cross-host networking <a class="header-anchor" href="#cross-host-networking" aria-label="Permalink to &quot;Cross-host networking&quot;">​</a></h2><p>For multi-node clusters, the endpoint controller resolves backend addresses differently depending on where the instance runs:</p><table tabindex="0"><thead><tr><th>Instance location</th><th>Backend address</th></tr></thead><tbody><tr><td>Local (same node)</td><td>Container IP:port</td></tr><tr><td>Remote (different node)</td><td>Node advertise address + Docker host port</td></tr></tbody></table><p>The <code>--advertise-address</code> flag on the agent publishes the node&#39;s LAN IP for cross-host resolution.</p><h2 id="vip-data-plane" tabindex="-1">VIP data plane <a class="header-anchor" href="#vip-data-plane" aria-label="Permalink to &quot;VIP data plane&quot;">​</a></h2><p>The data plane uses iptables DNAT rules with round-robin (via the <code>statistic</code> module):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VIP 10.200.0.1:80 → DNAT to:</span></span>
<span class="line"><span>  10.100.1.5:8080 (33%)</span></span>
<span class="line"><span>  10.100.2.8:8080 (33%)</span></span>
<span class="line"><span>  10.100.3.2:8080 (34%)</span></span></code></pre></div><p>Per-service iptables chains (<code>CCA_SVC_*</code>) are managed by the agent. A <code>cca0</code> dummy interface holds VIP addresses.</p><h2 id="identity-based-network-policies" tabindex="-1">Identity-based network policies <a class="header-anchor" href="#identity-based-network-policies" aria-label="Permalink to &quot;Identity-based network policies&quot;">​</a></h2><p>Network policies reference service identities, not IP addresses or label selectors:</p><div class="language-hcl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hcl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">network</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    allow frontend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">web </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> payments</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checkout port </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    allow payments</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checkout </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> payments</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">database port </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5432</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    deny frontend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">web </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> payments</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">database</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>When instances move between nodes, the policies don&#39;t change — only the derived firewall rules change. Every workload gets a SPIFFE identity (<code>spiffe://ccattler/payments/database</code>), and mTLS between services is automatic.</p>`,28)])])}const g=e(n,[["render",r]]);export{k as __pageData,g as default};
